cat > /root/autodl-tmp/diagprobe/test_sandbox_broad.py << 'PYEOF'
import json
from src.sandbox import execute_probe
from collections import Counter

with open('data/probes_train.jsonl') as f:
    samples = [json.loads(line) for line in f]

errors = Counter()
successes = 0
total = min(50, len(samples))

for i in range(total):
    s = samples[i]
    result = execute_probe(s['buggy_code'], s['good_probe'], timeout=5)
    if result.success:
        successes += 1
    else:
        err = result.stderr.strip().split('\n')[-1] if result.stderr.strip() else 'empty'
        if 'IndentationError' in err:
            errors['IndentationError'] += 1
        elif 'NameError' in err and 'List' in result.stderr:
            errors['NameError_List'] += 1
        elif 'NameError' in err:
            errors['NameError_other'] += 1
        elif 'SyntaxError' in err:
            errors['SyntaxError'] += 1
        elif 'Timeout' in err:
            errors['Timeout'] += 1
        elif 'TypeError' in err:
            errors['TypeError'] += 1
        elif 'AttributeError' in err:
            errors['AttributeError'] += 1
        else:
            errors[err[:80]] += 1

print(f"Total: {total}, Success: {successes} ({successes*100//total}%)")
print(f"Failures by type:")
for k, v in errors.most_common():
    print(f"  {k}: {v}")
PYEOF
echo "Written"
